"""ABI 类型布局诊断（编码前预检与结构说明）。

:func:`describeAbiType` 接受一个 ABI JSON 参数节点（含 ``type`` 文本，
tuple 或以 tuple 为元素的数组可带 ``components``），只做声明校验与
结构展开，返回纯字典诊断结果：不编解码、不读写文件，参数名与成员名
不进入结果。

诊断字典只含以下键并递归展开：

- ``canonical``：无空白、无名称、可直接用于签名的规范类型字符串，如
  ``uint256``、``bytes32``、``address[]``、``(bytes32,uint256)[2]``；
  别名按解析层既有规则归一（``uint``→``uint256`` 等）。
- ``kind``：``uint`` / ``int`` / ``address`` / ``bool`` / ``bytesN`` /
  ``bytes`` / ``string`` / ``fixed`` / ``ufixed`` / ``function`` /
  ``array`` / ``tuple``。
- ``isDynamic``：按 Solidity ABI 规则——``bytes``、``string``、动态
  数组、元素动态的数组、含动态成员的 tuple 为 True，其余 False。
- ``arrayLength``：定长数组为正整数，动态数组为 None，非数组为 None。
- ``base``：数组的元素诊断，其余类型为 None。
- ``components``：tuple 的子诊断列表（空 tuple 为 ``[]``）；数组链
  指向 tuple 时，每层数组的 components 都给出最内层 tuple 的子诊断，
  其余情形为 None。

错误约定（同输入稳定抛出同一异常，消息指出输入层级与字段，不含文件
路径）：

- 输入不是 dict、``type`` 不是字符串、tuple 缺 components 或
  components 不是列表：:class:`abi_kit.RangeError` 的姊妹异常
  :class:`TypeError`（Python 内置）；
- 类型语法、整数位宽、bytesN、fixedMxN、数组长度非法，或非 tuple
  声明带有 components：:class:`abi_kit.RangeError`。
"""

from __future__ import annotations

from ._exceptions import ABITypeError, RangeError
from ._parser import parse_abi_type
from ._types import (
    ABIType,
    ArrayType,
    ElementaryType,
    FixedPointType,
    FunctionType,
    TupleType,
)

#: tuple components 递归展开的安全上限，与事件/解析路径一致：语义嵌套
#: 上限（128 层）由类型对象构造时检查，此阈值仅用于在触及 Python 递归
#: 限制前抛出确定的 RangeError。
_RECURSION_SAFETY_LIMIT = 200

_TUPLE_PREFIX = "tuple"


def _type_error(location: str, message: str) -> TypeError:
    return TypeError(f"{location}：{message}")


def _range_error(location: str, message: str) -> RangeError:
    return RangeError(f"{location}：{message}")


def _split_tuple_suffix(type_string: str, location: str) -> str:
    """校验 ``tuple`` / ``tuple[...]`` 文本，返回数组后缀串（可能为空）。"""
    suffix = type_string[_TUPLE_PREFIX:]
    if not suffix:
        return ""
    index = 0
    length = len(suffix)
    while index < length:
        if suffix[index] != "[":
            raise _range_error(
                location, f"非法 tuple 类型文本：{type_string!r}"
            )
        index += 1
        if index >= length:
            raise _range_error(location, f"数组后缀不完整：{type_string!r}")
        if suffix[index] == "]":
            index += 1
            continue
        # 定长后缀只接受 [1-9][0-9]*：拒绝 0 长度与前导零。
        if not suffix[index].isdigit() or suffix[index] == "0":
            raise _range_error(
                location, f"数组长度必须是无前导零的正整数：{type_string!r}"
            )
        start = index
        while index < length and suffix[index].isdigit():
            index += 1
        if index >= length or suffix[index] != "]":
            raise _range_error(location, f"数组后缀缺少 ']'：{type_string!r}")
        index += 1
    return suffix


def _leaf_diagnostic(abi_type: ABIType) -> dict:
    """把非数组、非元组的叶子类型对象转为诊断字典。"""
    if isinstance(abi_type, ElementaryType):
        kind = abi_type.kind
        if kind in ("uint", "int"):
            canonical = f"{kind}{abi_type.bit_size}"
        elif kind == "bytes" and abi_type.byte_size is not None:
            canonical = f"bytes{abi_type.byte_size}"
            kind = "bytesN"
        else:
            canonical = kind
        return {
            "canonical": canonical,
            "kind": kind,
            "isDynamic": kind in ("bytes", "string"),
            "arrayLength": None,
            "base": None,
            "components": None,
        }
    if isinstance(abi_type, FixedPointType):
        prefix = "fixed" if abi_type.signed else "ufixed"
        return {
            "canonical": f"{prefix}{abi_type.bit_size}x{abi_type.scale}",
            "kind": prefix,
            "isDynamic": False,
            "arrayLength": None,
            "base": None,
            "components": None,
        }
    if isinstance(abi_type, FunctionType):
        # function 是 24 字节静态类型。
        return {
            "canonical": "function",
            "kind": "function",
            "isDynamic": False,
            "arrayLength": None,
            "base": None,
            "components": None,
        }
    raise _range_error("根类型声明", f"不支持的叶子类型：{abi_type!r}")


def _array_suffixes(abi_type: ABIType) -> list[int | None]:
    """收集数组类型对象由内向外的每层长度（None 表示动态层）。"""
    lengths: list[int | None] = []
    current = abi_type
    while isinstance(current, ArrayType):
        lengths.append(current.length)
        current = current.element_type
    return lengths


def _build(node, location: str, depth: int) -> dict:
    """从一个 ABI JSON 类型节点递归构造诊断字典。"""
    if depth > _RECURSION_SAFETY_LIMIT:
        raise _range_error(location, "components 嵌套过深")
    if not isinstance(node, dict):
        raise _type_error(
            location, f"类型声明必须是 JSON 对象，得到 {type(node).__name__}"
        )
    if "type" not in node:
        raise _type_error(location, "缺少 type 字段")
    type_string = node["type"]
    if not isinstance(type_string, str):
        raise _type_error(
            location, f"type 必须是字符串，得到 {type(type_string).__name__}"
        )
    if not type_string:
        raise _range_error(location, "type 不能为空字符串")

    has_components = "components" in node

    if type_string == _TUPLE_PREFIX or type_string.startswith("tuple["):
        suffix = _split_tuple_suffix(type_string, location)
        components_node = node.get("components")
        if not isinstance(components_node, list):
            if "components" not in node:
                raise _type_error(
                    location,
                    f"tuple 类型必须带有列表形式的 components：{type_string!r}",
                )
            raise _type_error(
                location,
                "components 必须是数组，"
                f"得到 {type(components_node).__name__}",
            )
        child_diagnostics = [
            _build(
                child,
                f"{location}.components[{index}]",
                depth + 1,
            )
            for index, child in enumerate(components_node)
        ]
        tuple_diagnostic = {
            "canonical": "("
            + ",".join(child["canonical"] for child in child_diagnostics)
            + ")",
            "kind": "tuple",
            "isDynamic": any(child["isDynamic"] for child in child_diagnostics),
            "arrayLength": None,
            "base": None,
            "components": child_diagnostics,
        }
        if not suffix:
            return tuple_diagnostic
        return _wrap_suffixes(tuple_diagnostic, suffix)

    if has_components:
        raise _range_error(
            location, f"非 tuple 类型不能带有 components：{type_string!r}"
        )

    # 非 tuple 路径：完全复用既有类型解析器，别名归一与全部语法/值域
    # 规则（位宽、bytesN、fixedMxN、数组长度等）与其保持一致。
    try:
        abi_type = parse_abi_type(type_string)
    except ABITypeError as exc:
        raise _range_error(location, f"非法类型文本 {type_string!r}：{exc}") from None

    return _diagnostic_from_type(abi_type)


def _wrap_suffixes(inner: dict, suffix: str) -> dict:
    """把已解析的 tuple 诊断按 ``[]`` / ``[n]`` 后缀逐层包成数组诊断。

    每层数组的 components 都透传最内层 tuple 的子诊断；嵌套数组元素
    （base）继续递归保留。后缀语法已由 :func:`_split_tuple_suffix`
    校验，这里只做逐层包装。
    """
    tuple_components = inner["components"]
    current = inner
    index = 0
    length = len(suffix)
    while index < length:
        # 循环不变量：suffix[index] == "["。
        index += 1
        if suffix[index] == "]":
            array_length = None
            index += 1
        else:
            start = index
            while suffix[index].isdigit():
                index += 1
            array_length = int(suffix[start:index])
            index += 1  # 跳过 ']'
        current = {
            "canonical": current["canonical"]
            + ("[]" if array_length is None else f"[{array_length}]"),
            "kind": "array",
            "isDynamic": array_length is None or current["isDynamic"],
            "arrayLength": array_length,
            "base": current,
            "components": tuple_components,
        }
    return current


def _diagnostic_from_type(abi_type: ABIType) -> dict:
    """把经解析器校验的类型对象转为诊断（支持数组链指向 tuple）。"""
    lengths = _array_suffixes(abi_type)
    if not lengths:
        if isinstance(abi_type, TupleType):
            # 经由类型文本（"(...)"）给出的元组：按文本形式同样展开。
            return _tuple_from_object(abi_type)
        return _leaf_diagnostic(abi_type)

    # 数组链：由内层向外构造，数组的 base 指向上一层诊断。
    innermost = abi_type
    while isinstance(innermost, ArrayType):
        innermost = innermost.element_type
    if isinstance(innermost, TupleType):
        current: dict = _tuple_from_object(innermost)
    else:
        current = _leaf_diagnostic(innermost)
    tuple_components = current["components"]
    for array_length in reversed(lengths):
        current = {
            "canonical": current["canonical"]
            + ("[]" if array_length is None else f"[{array_length}]"),
            "kind": "array",
            "isDynamic": array_length is None or current["isDynamic"],
            "arrayLength": array_length,
            "base": current,
            "components": tuple_components,
        }
    return current


def _tuple_from_object(abi_type: TupleType) -> dict:
    children = [_diagnostic_from_type(component) for component in abi_type.components]
    return {
        "canonical": "(" + ",".join(c["canonical"] for c in children) + ")",
        "kind": "tuple",
        "isDynamic": any(c["isDynamic"] for c in children),
        "arrayLength": None,
        "base": None,
        "components": children,
    }


def describeAbiType(node: dict) -> dict:
    """描述一个 ABI JSON 类型声明，返回纯字典布局诊断。

    典型用法（编码前预检）::

        describeAbiType({"type": "tuple[2]", "components": [
            {"type": "bytes32"}, {"type": "uint256"},
        ]})
        # {
        #   "canonical": "(bytes32,uint256)[2]",
        #   "kind": "array", "isDynamic": False, "arrayLength": 2,
        #   "base": { ...tuple 诊断... },
        #   "components": [ {...bytes32...}, {...uint256...} ],
        # }

    本入口只做声明校验与结构说明，不编解码、不读写文件；参数名与
    成员名不进入结果，同输入稳定得到同一结果。

    - 输入不是 dict、``type`` 缺失或不是字符串、tuple 缺 components 或
      components 不是数组时抛 :class:`TypeError`；
    - 类型文本语法、整数位宽、bytesN、fixedMxN、数组长度非法，或非
      tuple 声明带有 components 时抛 :class:`abi_kit.RangeError`。
    """
    if not isinstance(node, dict):
        raise TypeError(
            f"根类型声明必须是 JSON 对象，得到 {type(node).__name__}"
        )
    return _build(node, "根类型声明", 1)

