        return {
            "canonical": "function",
            "kind": "function",
            "isDynamic": False,
            "arrayLength": None,
            "base": None,
            "components": None,
        }
    raise _range_error("根类型声明", f"不支持的叶子类型：{abi_type!r}")


def _diagnostic(abi_type: ABIType) -> dict:
    """把经过校验的类型对象递归转为诊断字典。"""
